=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v. It drives one bus into two configurations of the design,
// N=8 (the approved configuration) and N=32 (the widest the design supports, which reaches the
// rdata and irq_id bits that are constant at N=8). Each instance is compared with a cycle-level
// reference model after every clock edge and at every register address; directed checks are
// added at chosen points. No coverage pragmas, includes or configuration are used here.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic [31:0] src = 32'd0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;

    logic [31:0] rdata8, rdata32, m_rdata8, m_rdata32;
    logic        irq8, irq32, m_irq8, m_irq32;
    logic [4:0]  irq_id8, irq_id32, m_irq_id8, m_irq_id32;

    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    irq_ctrl #(.N(8)) dut8 (.clk(clk), .rst_n(rst_n), .src(src[7:0]), .we(we), .addr(addr),
                            .wdata(wdata), .rdata(rdata8), .irq(irq8), .irq_id(irq_id8));
    irq_ctrl #(.N(32)) dut32 (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr),
                              .wdata(wdata), .rdata(rdata32), .irq(irq32), .irq_id(irq_id32));

    irq_ctrl_cov_model #(.N(8)) ref8 (.clk(clk), .rst_n(rst_n), .src(src[7:0]), .we(we), .addr(addr),
                                      .wdata(wdata), .rdata(m_rdata8), .irq(m_irq8), .irq_id(m_irq_id8));
    irq_ctrl_cov_model #(.N(32)) ref32 (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr),
                                        .wdata(wdata), .rdata(m_rdata32), .irq(m_irq32), .irq_id(m_irq_id32));

    always #5 clk = ~clk;

    // Compare both instances with their models at the current address.
    task automatic compare_models();
        checks++;
        if (rdata8 !== m_rdata8 || irq8 !== m_irq8 || irq_id8 !== m_irq_id8) errors++;
        checks++;
        if (rdata32 !== m_rdata32 || irq32 !== m_irq32 || irq_id32 !== m_irq_id32) errors++;
    endtask

    // Read every register address (only while we is low) and compare.
    task automatic sweep();
        for (int a = 0; a < 4; a++) begin
            addr = 2'(a);
            #1;
            compare_models();
        end
    endtask

    // One clock edge with the inputs as set, then drop we and check.
    task automatic cycle();
        @(posedge clk);
        #1;
        we = 1'b0;
        compare_models();
        sweep();
    endtask

    task automatic idle();
        cycle();
    endtask

    task automatic write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1;
        addr = a;
        wdata = d;
        cycle();
    endtask

    // Directed read check of both instances (only while we is low).
    task automatic expect_rd(input logic [1:0] a, input logic [31:0] e8, input logic [31:0] e32);
        addr = a;
        #1;
        checks++;
        if (rdata8 !== e8) errors++;
        checks++;
        if (rdata32 !== e32) errors++;
    endtask

    initial begin
        // Reset.
        repeat (3) @(posedge clk);
        #1;
        rst_n = 1'b1;
        cycle();
        expect_rd(2'd0, 32'd0, 32'd0);
        expect_rd(2'd1, 32'd0, 32'd0);
        expect_rd(2'd2, 32'd0, 32'd0);
        expect_rd(2'd3, 32'd0, 32'd0);

        // 1. ENABLE and MODE: every bit both ways; bits N and up ignored.
        write(2'd0, 32'hFFFF_FFFF);
        expect_rd(2'd0, 32'h0000_00FF, 32'hFFFF_FFFF);
        write(2'd0, 32'h0000_0000);
        expect_rd(2'd0, 32'd0, 32'd0);
        write(2'd0, 32'hA5A5_A5A5);
        expect_rd(2'd0, 32'h0000_00A5, 32'hA5A5_A5A5);
        write(2'd0, 32'h5A5A_5A5A);
        expect_rd(2'd0, 32'h0000_005A, 32'h5A5A_5A5A);
        write(2'd0, 32'd0);
        write(2'd1, 32'hFFFF_FFFF);
        expect_rd(2'd1, 32'h0000_00FF, 32'hFFFF_FFFF);
        write(2'd1, 32'h3C3C_C3C3);
        expect_rd(2'd1, 32'h0000_00C3, 32'h3C3C_C3C3);
        write(2'd1, 32'd0);
        expect_rd(2'd1, 32'd0, 32'd0);

        // 2. Level detection with every source masked: pending sets, irq stays low.
        src = 32'hFFFF_FFFF;
        idle();
        src = 32'd0;
        idle();
        expect_rd(2'd2, 32'h0000_00FF, 32'hFFFF_FFFF);
        expect_rd(2'd3, 32'd0, 32'd0);

        // 3. Write-one-to-clear in slices; bits written zero keep their state.
        write(2'd2, 32'h0000_000F);
        expect_rd(2'd2, 32'h0000_00F0, 32'hFFFF_FFF0);
        write(2'd2, 32'h0000_FFF0);
        expect_rd(2'd2, 32'h0000_0000, 32'hFFFF_0000);
        write(2'd2, 32'hFFFF_FFFF);
        expect_rd(2'd2, 32'd0, 32'd0);

        // 4. Priority walk: every source pending and enabled, acknowledged 0..31 in order.
        src = 32'hFFFF_FFFF;
        idle();
        src = 32'd0;
        idle();
        write(2'd0, 32'hFFFF_FFFF);
        expect_rd(2'd3, 32'h8000_0000, 32'h8000_0000);
        for (int k = 0; k < 32; k++) begin
            write(2'd3, 32'(k));
            if (k == 2) expect_rd(2'd3, 32'h8000_0003, 32'h8000_0003);
            if (k == 15) expect_rd(2'd3, 32'd0, 32'h8000_0010);
        end
        expect_rd(2'd3, 32'd0, 32'd0);
        expect_rd(2'd2, 32'd0, 32'd0);

        // 5. A detection wins over a clear at the same edge (level mode, sources held high).
        src = 32'h0000_0108;
        idle();
        write(2'd2, 32'h0000_0108);
        expect_rd(2'd2, 32'h0000_0008, 32'h0000_0108);
        write(2'd3, 32'd3);
        expect_rd(2'd2, 32'h0000_0008, 32'h0000_0108);
        expect_rd(2'd3, 32'h8000_0003, 32'h8000_0003);
        src = 32'd0;
        idle();
        expect_rd(2'd2, 32'h0000_0008, 32'h0000_0108);
        write(2'd2, 32'hFFFF_FFFF);
        expect_rd(2'd2, 32'd0, 32'd0);

        // 6. Rising-edge mode: a held source sets pending once; a clear while held high sticks.
        write(2'd1, 32'hFFFF_FFFF);
        src = 32'hFFFF_FFFF;
        idle();
        idle();
        expect_rd(2'd2, 32'h0000_00FF, 32'hFFFF_FFFF);
        write(2'd2, 32'hFFFF_FFFF);
        idle();
        expect_rd(2'd2, 32'd0, 32'd0);
        expect_rd(2'd3, 32'd0, 32'd0);
        src = 32'd0;
        idle();
        expect_rd(2'd2, 32'd0, 32'd0);

        // 7. Mixed modes (odd sources edge, even level) and an enable mask.
        write(2'd1, 32'hAAAA_AAAA);
        write(2'd0, 32'hFF00_00C0);
        src = 32'h0000_0001;
        idle();
        src = 32'd0;
        idle();
        expect_rd(2'd2, 32'h0000_0001, 32'h0000_0001);
        expect_rd(2'd3, 32'd0, 32'd0);
        write(2'd2, 32'h0000_0001);
        src = 32'h0100_00C0;
        idle();
        src = 32'd0;
        idle();
        expect_rd(2'd2, 32'h0000_00C0, 32'h0100_00C0);
        expect_rd(2'd3, 32'h8000_0006, 32'h8000_0006);
        write(2'd3, 32'd6);
        expect_rd(2'd3, 32'h8000_0007, 32'h8000_0007);
        write(2'd3, 32'hFFFF_FFE7);
        expect_rd(2'd3, 32'd0, 32'h8000_0018);
        write(2'd3, 32'd24);
        expect_rd(2'd3, 32'd0, 32'd0);
        expect_rd(2'd2, 32'd0, 32'd0);

        // 8. Reset in the middle of operation clears every register.
        write(2'd0, 32'hFFFF_FFFF);
        write(2'd1, 32'h0F0F_0F0F);
        src = 32'h0000_0011;
        idle();
        expect_rd(2'd3, 32'h8000_0000, 32'h8000_0000);
        expect_rd(2'd2, 32'h0000_0011, 32'h0000_0011);
        rst_n = 1'b0;
        idle();
        idle();
        expect_rd(2'd0, 32'd0, 32'd0);
        expect_rd(2'd1, 32'd0, 32'd0);
        expect_rd(2'd2, 32'd0, 32'd0);
        expect_rd(2'd3, 32'd0, 32'd0);
        src = 32'd0;
        rst_n = 1'b1;
        idle();
        idle();
        expect_rd(2'd0, 32'd0, 32'd0);
        expect_rd(2'd1, 32'd0, 32'd0);
        expect_rd(2'd2, 32'd0, 32'd0);
        expect_rd(2'd3, 32'd0, 32'd0);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule

// Cycle-level reference model of the irq_ctrl register interface, written from the
// register description: per-source enable, mode (1 = rising edge, 0 = high level),
// write-one-to-clear pending where a detection wins over a clear, acknowledge of the
// source a CLAIM write names, and the lowest-numbered pending enabled source claimed.
module irq_ctrl_cov_model #(
    parameter int N = 8
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [N-1:0] src,
    input  logic         we,
    input  logic [1:0]   addr,
    input  logic [31:0]  wdata,
    output logic [31:0]  rdata,
    output logic         irq,
    output logic [4:0]   irq_id
);
    logic [N-1:0] m_enable, m_mode, m_pending, m_prev;
    logic [N-1:0] m_set, m_clear, m_active;
    logic         m_found;

    always_comb begin
        m_set = '0;
        m_clear = '0;
        for (int k = 0; k < N; k++) begin
            if (m_mode[k]) m_set[k] = src[k] && !m_prev[k];
            else           m_set[k] = src[k];
            if (we && addr == 2'd2 && wdata[k]) m_clear[k] = 1'b1;
            if (we && addr == 2'd3 && int'(wdata[4:0]) == k) m_clear[k] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            m_enable  <= '0;
            m_mode    <= '0;
            m_pending <= '0;
            m_prev    <= '0;
        end else begin
            m_prev    <= src;
            m_pending <= m_set | (m_pending & ~m_clear);
            if (we && addr == 2'd0) m_enable <= wdata[N-1:0];
            if (we && addr == 2'd1) m_mode <= wdata[N-1:0];
        end
    end

    assign m_active = m_pending & m_enable;

    always_comb begin
        irq = |m_active;
        irq_id = 5'd0;
        m_found = 1'b0;
        for (int k = 0; k < N; k++) begin
            if (!m_found && m_active[k]) begin
                irq_id = 5'(k);
                m_found = 1'b1;
            end
        end
    end

    always_comb begin
        rdata = 32'd0;
        case (addr)
            2'd0:    rdata[N-1:0] = m_enable;
            2'd1:    rdata[N-1:0] = m_mode;
            2'd2:    rdata[N-1:0] = m_pending;
            default: rdata = {irq, 26'd0, irq_id};
        endcase
    end
endmodule
=== END FILE ===
